// Calendar — Gtk.Calendar
//
// Generated by bin/11-generate-components, which does not overwrite.
//
// It ships no template, so the markup is the one element its CSS node is, carrying what
  // Adwaita styles calendar with.

import type { ReactNode } from "react"

import { cn } from "@/lib/utils"
import type { WidgetProps } from "@/lib/widget-props"

export interface CalendarProps extends WidgetProps {
  className?: string
  children?: ReactNode
  /** GLib.DateTime, from Gtk.Calendar */
  date?: ReactNode

  /** gint, from Gtk.Calendar */
  day?: number

  /** gint, from Gtk.Calendar */
  month?: number

  /** gboolean, from Gtk.Calendar */
  showDayNames?: boolean

  /** gboolean, from Gtk.Calendar */
  showHeading?: boolean

  /** gboolean, from Gtk.Calendar */
  showWeekNumbers?: boolean

  /** gint, from Gtk.Calendar */
  year?: number
}

export function Calendar({ className, children }: CalendarProps) {
  return (
    <div className={cn("text-[var(--view-fg-color)]", "bg-clip-padding", className)}>
      {children}
    </div>
  )
}
